import {test,expect,type Page,type Browser,type WebSocketRoute} from '@playwright/test';
import {randomUUID} from 'node:crypto';
import {keypadHit} from '../../src/domain/scoring';
import {createDeckGame,deckAction,shuffledDeck,type DeckGame,type DeckSettings} from '../../src/domain/dartdeck';
import {createMinigame,minigameAction,withMinigameHistory} from '../../src/domain/minigames';
const a=randomUUID(),b=randomUUID();
async function fixture(page:Page,browser:Browser,phase:'waiting'|'playing'='playing',shared=false,overrides:Partial<DeckSettings>={},commonBingo=false,individualBingo=false){
 const id=randomUUID();let version=1,created=phase==='playing',settings:DeckSettings={rounds:1,difficulty:'mixed',...overrides},game:DeckGame|null=null,last:DeckGame|null=null;
 let members:any[]=[{id:randomUUID(),account_id:a,controller_id:a,name:'Alice',local:false,accepted:true},{id:randomUUID(),account_id:shared?null:b,controller_id:shared?a:b,name:'Bob',local:shared,accepted:true},{id:randomUUID(),account_id:null,controller_id:a,name:'Carla',local:true,accepted:true}];
 if(phase==='waiting')members=members.slice(0,1);
 const begin=()=>{const pile=shuffledDeck(settings.difficulty,()=>0),first='sector-20-1';pile.splice(pile.indexOf(first),1);pile.unshift(first);const roster=members.map(p=>({id:p.id,name:p.name,controllerId:p.controller_id,accountId:p.account_id}));game=withMinigameHistory(settings.mode&&settings.mode!=='dartdeck'?createMinigame(roster,settings,()=>0):createDeckGame(roster,settings,pile),last);if(game.bingo&&!individualBingo){delete game.bingo.markAll;game.bingo.shared=commonBingo;}};if(created)begin();
 const publicGame=(g:DeckGame|null)=>{if(!g)return null;const {deck:_deck,...view}=g;return view;};
 const room=()=>({id,host_id:a,phase:game?.phase??'waiting',settings,game:publicGame(game),last_game:publicGame(last),version,created_at:new Date().toISOString()});
 async function attach(p:Page,account:string){
  await p.addInitScript(()=>{localStorage.setItem('dartdeck-input','keyboard');HTMLElement.prototype.requestFullscreen=()=>Promise.reject(new DOMException('Gesture required','NotAllowedError'));});
  await p.route('**/api/identity',r=>r.fulfill({json:{signedIn:true,role:'owner',id:account,setupRequired:false}}));
  await p.route('**/api/autodarts',r=>r.fulfill({json:{authenticated:false,canLink:false}}));
  await p.route('**/api/dartdeck-image**',r=>r.fulfill({json:r.request().method()==='GET'?{image:null}:{ok:true,accepted:true}}));
  await p.route('**/api/device-accounts',r=>r.fulfill({json:{accounts:[{id:account,name:account===a?'Alice':'Bob',primary:true}]}}));
  await p.route('**/api/players?**',r=>r.fulfill({json:{players:[{id:b,handle:'bob',name:'Bob',friend:true}]}}));
  await p.route('**/api/friends**',async r=>{if(r.request().method()==='GET'){await r.fulfill({json:{account:true,handle:account===a?'alice':'bob',friends:[],invitations:members.filter(m=>m.account_id===account&&!m.accepted).map(m=>({id:m.id,roomId:id,name:'DartDeck',from:'Alice',kind:'dartdeck'}))}});return;}const d=r.request().postDataJSON();const member=members.find(m=>m.id===d.id&&m.account_id===account);if(d.operation==='invitation'&&member){member.accepted=true;version++;await r.fulfill({json:{ok:true,redirect:'/minigames/'+id}});}else await r.fulfill({json:{ok:true}});});
  await p.route('**/api/dartdeck**',async r=>{
   if(r.request().method()==='GET'){const query=new URL(r.request().url()).searchParams.has('id');await r.fulfill({json:query?{room:room(),members,host:account===a,controlled:members.filter(m=>m.accepted&&m.controller_id===account).map(m=>m.id),accountIds:[account]}:{rooms:created?[{...room(),canDelete:account===a}]:[],accountIds:[account]}});return;}
   const d=r.request().postDataJSON();try{
    if(d.operation==='create'){created=true;settings=d.settings;await r.fulfill({json:{ok:true,redirect:'/minigames/'+id}});return;}
    if(d.expectedVersion!==version&&!(d.operation==='action'&&d.action.type==='vote-skip')){await r.fulfill({status:409,json:{error:'Stand geändert',conflict:true}});return;}
    if(d.operation==='local'){members.push({id:randomUUID(),account_id:null,controller_id:a,name:d.name,local:true,accepted:true});}
    if(d.operation==='invite')members.push({id:randomUUID(),account_id:b,controller_id:b,name:'Bob',local:false,accepted:false});
    if(d.operation==='settings')settings=d.settings;
    if(d.operation==='delete'){created=false;await r.fulfill({json:{ok:true,redirect:'/minigames'}});return;}
    if(d.operation==='start'){if(members.some(m=>!m.accepted))throw Error('Open invitation');begin();}
    if(d.operation==='rematch'){last=game;game=null;}
    if(d.operation==='action'){if(!members.some(m=>m.id===d.actor&&m.controller_id===account))throw Error('Not your player');game=minigameAction(game!,d.actor,d.action);}
    version++;await r.fulfill({json:{ok:true,...(d.operation==='action'?{game:publicGame(game),version}:{})}});
   }catch(e){await r.fulfill({status:400,json:{error:String(e)}});}
  });
  await p.route('**/*.supabase.co/**',r=>r.abort());
 }
 await attach(page,a);const context=await browser.newContext({viewport:page.viewportSize()??undefined}),other=await context.newPage();await attach(other,b);
 return {id,other,get game(){return game!;},get members(){return members;},attach,close:()=>context.close()};
}
async function vote(page:Page,name:string){const active=await page.locator('.deck-turn strong').textContent();await (active?.startsWith(name)?page.locator('.deck-card'):page.locator('.deck-player').filter({has:page.getByText(name,{exact:true})})).getByRole('button',{name:'Vote Skip',exact:true}).click();}
test('separate lobby accepts account invitations and supports more than six local players',async({page,browser})=>{
 const s=await fixture(page,browser,'waiting');try{
  await page.goto('/minigames');await expect(page.getByRole('link',{name:'Minigames',exact:true})).toHaveAttribute('aria-current','page');await expect(page.getByLabel('Spielmodus',{exact:true})).toBeVisible();
  await page.getByRole('button',{name:'Lobby eröffnen',exact:true}).click();await expect(page).toHaveURL('/minigames/'+s.id);
  await page.getByRole('button',{name:'Spieler einladen / lokal hinzufügen',exact:true}).click();
  for(let i=1;i<=7;i++){await page.getByLabel('Lokaler Spieler',{exact:true}).fill('Local '+i);await page.getByRole('button',{name:'Lokal hinzufügen',exact:true}).click();await expect(page.locator('.deck-members .compact-row')).toHaveCount(i+1);}
  await page.getByRole('option',{name:/bob/}).click();await expect(page.getByRole('button',{name:'Partie starten',exact:true})).toBeDisabled();
  await s.other.goto('/friends');await s.other.getByRole('button',{name:'Öffnen',exact:true}).click();await expect(s.other).toHaveURL('/minigames/'+s.id);await expect(page.getByRole('button',{name:'Partie starten',exact:true})).toBeEnabled();
  await page.getByRole('button',{name:'Partie starten',exact:true}).click();await expect(page.locator('.deck-card')).toBeVisible();expect(s.game.players).toHaveLength(9);
 }finally{await s.close();}
});
test('unanimous vote skips the shared card on both devices without changing player',async({page,browser},info)=>{
 const s=await fixture(page,browser);try{
  await page.goto('/minigames/'+s.id);await s.other.goto('/minigames/'+s.id);await expect(page.locator('.sidebar')).toHaveCount(0);await expect(page.locator('.topbar')).toHaveCount(0);await expect(page.locator('.deck-scoreboard .deck-player.active')).toContainText('Alice');await expect(page.locator('.deck-scoreboard')).not.toContainText('Average');await page.locator('.number-pad').getByRole('button',{name:'1',exact:true}).click();await expect(page.locator('.deck-darts button').first()).toContainText('S1');
  const old=await page.locator('.deck-card').getAttribute('data-card-id');
  for(const name of ['Alice','Carla'])await vote(page,name);
  await expect(page.locator('.deck-card')).toHaveAttribute('data-card-id',old!);
  await vote(s.other,'Bob');
  await expect(page.locator('.deck-card')).not.toHaveAttribute('data-card-id',old!);await expect(page.getByText('Karte übersprungen',{exact:true})).toBeVisible();await expect(page.locator('.deck-turn strong')).toHaveText('Alice ist dran');await expect(page.locator('.deck-darts button').first()).toContainText('—');expect(s.game.visits).toHaveLength(0);
  await s.other.reload();await expect(s.other.locator('.deck-card')).toHaveAttribute('data-card-id',s.game.cardId);expect(await page.locator('body').evaluate(el=>el.scrollWidth)).toBeLessThanOrEqual(page.viewportSize()!.width);await page.screenshot({path:'test-results/'+info.project.name+'-dartdeck.png',fullPage:true});
 }finally{await s.close();}
});
