test('Connect Four drops one coin per dart, rerolls per round and finishes a horizontal four',async({page,browser},info)=>{
 const s=await fixture(page,browser,'waiting');try{await page.goto('/minigames');await page.getByLabel('Spielmodus',{exact:true}).selectOption('connect-four');await page.getByLabel('Spielstärke',{exact:true}).selectOption('easy');await page.getByRole('button',{name:'Lobby eröffnen',exact:true}).click();await page.getByRole('button',{name:'Spieler einladen / lokal hinzufügen',exact:true}).click();await page.getByLabel('Lokaler Spieler',{exact:true}).fill('Yellow');await page.getByRole('button',{name:'Lokal hinzufügen',exact:true}).click();await page.getByRole('button',{name:'Partie starten',exact:true}).click();await expect(page.locator('.c4-cell')).toHaveCount(42);await expect(page.locator('.c4-targets strong')).toHaveCount(7);await expect(page.locator('.deck-darts button')).toHaveCount(1);const targets=structuredClone(s.game.connectFour!.targets);const drop=async(col:number)=>{const n=s.game.connectFour!.targets[col].number;await page.locator('.number-pad').getByRole('button',{name:String(n),exact:true}).click();await expect(page.locator('.number-pad button').first()).toBeDisabled();};const next=async()=>{const length=s.game.visits.length;await page.getByRole('button',{name:'Weiter →',exact:true}).click();await expect.poll(()=>s.game.visits.length).toBe(length+1);};await drop(0);await expect(page.locator('.c4-cell').nth(35).locator('.c4-coin')).toHaveCSS('animation-name','c4-drop');await page.evaluate(()=>{(window as any).firstCoin=document.querySelector('.c4-coin');window.dispatchEvent(new Event('focus'));});await next();expect(s.game.connectFour!.targets).toEqual(targets);await drop(0);await expect(page.locator('.c4-cell').nth(28)).toHaveAttribute('data-owner',s.members[1].id);await next();await expect(page.locator('.deck-player').first()).toContainText('Rot · 1');await expect(page.locator('.deck-player').nth(1)).toContainText('Gelb · 1');expect(s.game.connectFour!.targets).not.toEqual(targets);expect(await page.evaluate(()=>(window as any).firstCoin===document.querySelector('.c4-coin.red'))).toBe(true);await page.screenshot({path:'test-results/'+info.project.name+'-connect-four.png',fullPage:true});expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(page.viewportSize()!.width);for(const col of [1,6,2,6,3]){await drop(col);await next();}expect(s.game.phase).toBe('finished');await page.getByRole('button',{name:'Ergebnis ansehen',exact:true}).click();await expect(page.locator('.c4-cell.winning')).toHaveCount(4);await expect(page.locator('.deck-result h2')).toContainText('Alice');await expect(page.locator('.deck-history')).toContainText('Vier gewinnt');
 }finally{await s.close();}
});
