test('tablet lobby picker has compact local inputs and native scrolling through a long account list',async({page,browser},info)=>{
 const s=await fixture(page,browser,'waiting');try{await page.setViewportSize({width:1024,height:768});await page.route('**/api/players?**',r=>r.fulfill({json:{players:Array.from({length:35},(_,i)=>({id:randomUUID(),handle:'friend_'+i,name:'Friend '+i,friend:true}))}}));await page.goto('/minigames');await page.getByRole('button',{name:'Lobby eröffnen',exact:true}).click();await page.getByRole('button',{name:'Spieler einladen / lokal hinzufügen',exact:true}).click();await expect(page.locator('.account-options').getByRole('option')).toHaveCount(35);const input=page.getByLabel('Lokaler Spieler',{exact:true}),button=page.getByRole('button',{name:'Lokal hinzufügen',exact:true});expect((await input.boundingBox())!.height).toBeLessThan(70);expect((await button.boundingBox())!.height).toBeLessThan(70);const list=page.getByRole('listbox',{name:'Spielerkonten',exact:true});await list.hover();if(info.project.name==='mobile'){const box=(await list.boundingBox())!,client=await page.context().newCDPSession(page),x=box.x+box.width/2,y=box.y+box.height-20;await client.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x,y}]});for(let i=1;i<=5;i++){await client.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x,y:y-i*35}]});await page.waitForTimeout(20);}await client.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await client.detach();}else await page.mouse.wheel(0,900);await expect.poll(()=>list.evaluate(el=>el.scrollTop)).toBeGreaterThan(0);await list.evaluate(el=>el.scrollTop=el.scrollHeight);await expect(list.getByRole('option').last()).toBeInViewport();await page.screenshot({path:'test-results/'+info.project.name+'-lobby-picker-tablet.png',fullPage:true});await page.evaluate(()=>window.scrollTo(0,0));await page.mouse.move(1010,600);await page.mouse.wheel(0,700);await expect.poll(()=>page.evaluate(()=>window.scrollY)).toBeGreaterThan(0);expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(1024);
 }finally{await s.close();}
});
for(const mode of ['connect-four','tic-tac-toe'] as const)test(`${mode} consumes extra Autodarts detections without accepting a second dart or pausing`,async({page,browser})=>{
 const s=await fixture(page,browser,'waiting');let sockets:WebSocketRoute[]=[];try{await page.route('**/api/autodarts',r=>{const d=r.request().method()==='POST'?r.request().postDataJSON():null;return r.fulfill({json:!d?{authenticated:true,linked:true,canLink:true}:d.operation==='boards'?{boards:[{id:'shared',name:'Board'}],boardId:'shared',autoConnect:true}:d.operation==='ticket'?{url:'wss://play.ws.autodarts.com/test',boardEmpty:true}:{ok:true}});});await page.routeWebSocket('wss://play.ws.autodarts.com/**',ws=>sockets.push(ws));await page.goto('/minigames');await page.getByLabel('Spielmodus',{exact:true}).selectOption(mode);await page.getByLabel('Spielstärke',{exact:true}).selectOption('easy');await page.getByRole('button',{name:'Lobby eröffnen',exact:true}).click();await page.getByRole('button',{name:'Spieler einladen / lokal hinzufügen',exact:true}).click();await page.getByLabel('Lokaler Spieler',{exact:true}).fill('Local B');await page.getByRole('button',{name:'Lokal hinzufügen',exact:true}).click();await page.getByRole('button',{name:'Partie starten',exact:true}).click();await expect(page.locator('.deck-darts button')).toHaveCount(1);await expect(page.locator('.deck-turn strong')).toHaveText('Alice ist dran');await expect.poll(()=>sockets.length).toBe(1);const target=(mode==='connect-four'?s.game.connectFour!:s.game.ticTacToe!).targets[0];for(let n=1;n<=3;n++)sockets[0].send(JSON.stringify({channel:'autodarts.boards',topic:'shared.events',data:{event:'Throw detected',throwNumber:n,throw:{segment:{number:target.number,multiplier:target.multiplier??1}}}}));await expect.poll(()=>s.game.current.length).toBe(1);sockets[0].send(JSON.stringify({channel:'autodarts.boards',topic:'shared.events',data:{event:'Takeout finished'}}));await expect.poll(()=>s.game.visits.length).toBe(1);expect(s.game.visits[0].darts).toHaveLength(1);expect(s.game.visits[0].won).toBe(1);await expect(page.locator('.notice.error')).toHaveCount(0);expect(sockets.length).toBe(1);
 }finally{await s.close();}
});
